public class IdleState implements ElevatorState {
    public void step(Elevator car) {
        Integer next = car.nextStopAnyDirection();
        if (next == null) return;                          // rest
        car.setDirection(next > car.getCurrentFloor() ? Direction.UP : Direction.DOWN);
        car.setState(new MovingState());
    }
}

public class MovingState implements ElevatorState {
    public void step(Elevator car) {
        car.moveOneFloor();                                // one floor per tick
        if (car.isStop(car.getCurrentFloor())) {
            car.clearStop(car.getCurrentFloor());
            car.getDoor().open();
            car.setState(new DoorOpenState());
        }
    }
}

public class DoorOpenState implements ElevatorState {
    private int dwell = 2;                                 // ticks the doors stay open
    public void step(Elevator car) {
        if (car.isOverloaded()) return;                    // safety outranks the timer
        if (--dwell > 0) return;
        if (!car.getDoor().close()) { dwell = 2; return; } // obstructed: reopen and re-dwell
        car.setState(car.hasStops() ? new MovingState() : new IdleState());
        if (!car.hasStops()) car.setDirection(Direction.NONE);
    }
}

