public class Elevator {
    private final int id;
    private int currentFloor = 0;
    private Direction direction = Direction.NONE;
    private final NavigableSet<Integer> stops = new ConcurrentSkipListSet<>();
    private ElevatorState state = new IdleState();
    private final Door door = new Door();
    private volatile boolean overloaded;
    private volatile boolean inService = true;

    public Elevator(int id) { this.id = id; }

    public void addStop(int floor) { if (floor != currentFloor) stops.add(floor); }
    public void step() { if (inService) state.step(this); }

    // LOOK: next stop in the current direction, else any
    public Integer nextStopAnyDirection() {
        return direction == Direction.DOWN
            ? (stops.floor(currentFloor) != null ? stops.floor(currentFloor) : stops.ceiling(currentFloor))
            : (stops.ceiling(currentFloor) != null ? stops.ceiling(currentFloor) : stops.floor(currentFloor));
    }
    public void moveOneFloor() {
        Integer next = nextStopAnyDirection();
        if (next == null) return;
        direction = next > currentFloor ? Direction.UP : Direction.DOWN;
        currentFloor += direction == Direction.UP ? 1 : -1;
    }
    public boolean isStop(int f) { return stops.contains(f); }
    public void clearStop(int f) { stops.remove(f); }
    public boolean hasStops() { return !stops.isEmpty(); }

    // plumbing for states and the controller
    public int getCurrentFloor() { return currentFloor; }
    public Direction getDirection() { return direction; }
    public void setDirection(Direction d) { direction = d; }
    public void setState(ElevatorState s) { state = s; }
    public Door getDoor() { return door; }
    public boolean isOverloaded() { return overloaded; }
    public boolean isInService() { return inService; }
    public void setInService(boolean b) { inService = b; }
    public int getId() { return id; }
}

