#include <memory>
#include <optional>
#include <set>

class Elevator {
public:
    explicit Elevator(int id) : id_(id) {}

    void addStop(int floor) { if (floor != currentFloor_) stops_.insert(floor); }
    void step() { if (inService_) state_->step(*this); }

    // LOOK: next stop in the current direction, else any
    std::optional<int> nextStopAnyDirection() {
        if (stops_.empty()) return std::nullopt;
        if (direction_ == Direction::DOWN) {
            auto it = stops_.upper_bound(currentFloor_);
            if (it != stops_.begin()) return *std::prev(it);
            return *stops_.begin();
        }
        auto it = stops_.lower_bound(currentFloor_);
        if (it != stops_.end()) return *it;
        return *stops_.rbegin();
    }
    void moveOneFloor() {
        auto next = nextStopAnyDirection();
        if (!next) return;
        direction_ = *next > currentFloor_ ? Direction::UP : Direction::DOWN;
        currentFloor_ += direction_ == Direction::UP ? 1 : -1;
    }
    bool isStop(int f) const { return stops_.count(f) > 0; }
    void clearStop(int f) { stops_.erase(f); }
    bool hasStops() const { return !stops_.empty(); }

    // plumbing for states and the controller
    int getCurrentFloor() const { return currentFloor_; }
    Direction getDirection() const { return direction_; }
    void setDirection(Direction d) { direction_ = d; }
    void setState(std::shared_ptr<ElevatorState> s) { state_ = std::move(s); }
    Door& getDoor() { return door_; }
    bool isOverloaded() const { return overloaded_; }
    bool isInService() const { return inService_; }
    void setInService(bool b) { inService_ = b; }
    int getId() const { return id_; }

private:
    int id_;
    int currentFloor_ = 0;
    Direction direction_ = Direction::NONE;
    std::set<int> stops_;
    std::shared_ptr<ElevatorState> state_ = std::make_shared<IdleState>();
    Door door_;
    bool overloaded_ = false;
    bool inService_ = true;
};

void IdleState::step(Elevator& car) {
    auto next = car.nextStopAnyDirection();
    if (!next) return;                                     // rest
    car.setDirection(*next > car.getCurrentFloor() ? Direction::UP : Direction::DOWN);
    car.setState(std::make_shared<MovingState>());
}
void MovingState::step(Elevator& car) {
    car.moveOneFloor();                                    // one floor per tick
    if (car.isStop(car.getCurrentFloor())) {
        car.clearStop(car.getCurrentFloor());
        car.getDoor().open();
        car.setState(std::make_shared<DoorOpenState>());
    }
}
void DoorOpenState::step(Elevator& car) {
    if (car.isOverloaded()) return;                        // safety outranks the timer
    if (--dwell_ > 0) return;
    if (!car.getDoor().close()) { dwell_ = 2; return; }     // obstructed: reopen and re-dwell
    car.setState(car.hasStops() ? std::static_pointer_cast<ElevatorState>(std::make_shared<MovingState>())
                                 : std::static_pointer_cast<ElevatorState>(std::make_shared<IdleState>()));
    if (!car.hasStops()) car.setDirection(Direction::NONE);
}

