from typing import Optional


class Elevator:
    def __init__(self, elevator_id: int):
        self._id = elevator_id
        self._current_floor = 0
        self._direction = Direction.NONE
        self._stops: set = set()
        self._state: ElevatorState = IdleState()
        self._door = Door()
        self._overloaded = False
        self._in_service = True

    def add_stop(self, floor: int) -> None:
        if floor != self._current_floor:
            self._stops.add(floor)

    def step(self) -> None:
        if self._in_service:
            self._state.step(self)

    # LOOK: next stop in the current direction, else any
    def next_stop_any_direction(self) -> Optional[int]:
        if not self._stops:
            return None
        if self._direction == Direction.DOWN:
            below = [s for s in self._stops if s <= self._current_floor]
            return max(below) if below else min(self._stops)
        above = [s for s in self._stops if s >= self._current_floor]
        return min(above) if above else max(self._stops)

    def move_one_floor(self) -> None:
        nxt = self.next_stop_any_direction()
        if nxt is None:
            return
        self._direction = Direction.UP if nxt > self._current_floor else Direction.DOWN
        self._current_floor += 1 if self._direction == Direction.UP else -1

    def is_stop(self, f: int) -> bool: return f in self._stops
    def clear_stop(self, f: int) -> None: self._stops.discard(f)
    def has_stops(self) -> bool: return len(self._stops) > 0

    # plumbing for states and the controller
    def get_current_floor(self) -> int: return self._current_floor
    def get_direction(self) -> "Direction": return self._direction
    def set_direction(self, d: "Direction") -> None: self._direction = d
    def set_state(self, s: ElevatorState) -> None: self._state = s
    def get_door(self) -> Door: return self._door
    def is_overloaded(self) -> bool: return self._overloaded
    def is_in_service(self) -> bool: return self._in_service
    def set_in_service(self, b: bool) -> None: self._in_service = b
    def get_id(self) -> int: return self._id

