public class NearestCarStrategy implements SchedulingStrategy {
    public Elevator pickCar(List<Elevator> cars, HallRequest req) {
        Elevator best = null;
        int bestScore = Integer.MAX_VALUE;
        for (Elevator car : cars) {
            int distance = Math.abs(car.getCurrentFloor() - req.getFloor());
            boolean onTheWay =
                (car.getDirection() == Direction.UP && req.getDirection() == Direction.UP
                    && car.getCurrentFloor() <= req.getFloor()) ||
                (car.getDirection() == Direction.DOWN && req.getDirection() == Direction.DOWN
                    && car.getCurrentFloor() >= req.getFloor()) ||
                car.getDirection() == Direction.NONE;
            int score = distance + (onTheWay ? 0 : 100);   // penalise cars going the wrong way
            if (score < bestScore) { bestScore = score; best = car; }
        }
        return best;
    }
}

public class ElevatorController {
    private final List<Elevator> cars = new ArrayList<>();
    private final SchedulingStrategy strategy;
    private final int floors;
    private final Set<String> pending = ConcurrentHashMap.newKeySet();

    public ElevatorController(int carCount, int floors, SchedulingStrategy strategy) {
        this.floors = floors; this.strategy = strategy;
        for (int i = 0; i < carCount; i++) cars.add(new Elevator(i));
    }

    public void requestPickup(int floor, Direction dir) {
        if (floor < 0 || floor >= floors) throw new InvalidFloorException(floor);
        if (!pending.add(floor + ":" + dir)) return;       // atomic dedup
        synchronized (this) {
            List<Elevator> inService = cars.stream().filter(Elevator::isInService).toList();
            if (inService.isEmpty()) { pending.remove(floor + ":" + dir); throw new NoCarAvailableException(); }
            strategy.pickCar(inService, new HallRequest(floor, dir)).addStop(floor);
        }
    }
    public void requestFloor(int carId, int floor) {
        if (floor < 0 || floor >= floors) throw new InvalidFloorException(floor);
        cars.get(carId).addStop(floor);
    }
    public void step() {
        for (Elevator car : cars) {
            int before = car.getCurrentFloor();
            car.step();
            if (car.getCurrentFloor() != before)           // clear served hall keys
                pending.removeIf(k -> k.startsWith(car.getCurrentFloor() + ":"));
        }
    }
}

public class Demo {
    public static void main(String[] args) {
        ElevatorController ctrl = new ElevatorController(2, 15, new NearestCarStrategy());
        ctrl.requestPickup(5, Direction.UP);   // rider on 5 going up
        ctrl.requestPickup(3, Direction.UP);   // rider on 3 going up
        for (int t = 0; t < 8; t++) ctrl.step();
        ctrl.requestFloor(0, 12);              // rider boarded car 0, wants 12
        for (int t = 0; t < 12; t++) ctrl.step();
        // one sweep serves 3, then 5, then 12
    }
}

