class InvalidFloorException : public std::runtime_error {
public: explicit InvalidFloorException(int f) : std::runtime_error("invalid floor " + std::to_string(f)) {}
};
class NoCarAvailableException : public std::runtime_error {
public: NoCarAvailableException() : std::runtime_error("no car available") {}
};

class NearestCarStrategy : public SchedulingStrategy {
public:
    Elevator* pickCar(const std::vector<Elevator*>& cars, const HallRequest& req) override {
        Elevator* best = nullptr;
        int bestScore = INT_MAX;
        for (Elevator* car : cars) {
            int distance = std::abs(car->getCurrentFloor() - req.getFloor());
            bool onTheWay =
                (car->getDirection() == Direction::UP && req.getDirection() == Direction::UP
                    && car->getCurrentFloor() <= req.getFloor()) ||
                (car->getDirection() == Direction::DOWN && req.getDirection() == Direction::DOWN
                    && car->getCurrentFloor() >= req.getFloor()) ||
                car->getDirection() == Direction::NONE;
            int score = distance + (onTheWay ? 0 : 100);    // penalise cars going the wrong way
            if (score < bestScore) { bestScore = score; best = car; }
        }
        return best;
    }
};

class ElevatorController {
public:
    ElevatorController(int carCount, int floors, std::unique_ptr<SchedulingStrategy> strategy)
        : floors_(floors), strategy_(std::move(strategy)) {
        for (int i = 0; i < carCount; i++) cars_.push_back(std::make_unique<Elevator>(i));
    }

    void requestPickup(int floor, Direction dir) {
        if (floor < 0 || floor >= floors_) throw InvalidFloorException(floor);
        std::string key = std::to_string(floor) + ":" + std::to_string(static_cast<int>(dir));
        if (pending_.count(key)) return;                    // atomic dedup
        pending_.insert(key);
        std::vector<Elevator*> inService;
        for (auto& c : cars_) if (c->isInService()) inService.push_back(c.get());
        if (inService.empty()) { pending_.erase(key); throw NoCarAvailableException(); }
        Elevator* car = strategy_->pickCar(inService, HallRequest(floor, dir));
        car->addStop(floor);
    }
    void requestFloor(int carId, int floor) {
        if (floor < 0 || floor >= floors_) throw InvalidFloorException(floor);
        cars_[carId]->addStop(floor);
    }
    void step() {
        for (auto& car : cars_) {
            int before = car->getCurrentFloor();
            car->step();
            if (car->getCurrentFloor() != before) {        // clear served hall keys
                std::string prefix = std::to_string(car->getCurrentFloor()) + ":";
                for (auto it = pending_.begin(); it != pending_.end();) {
                    if (it->rfind(prefix, 0) == 0) it = pending_.erase(it); else ++it;
                }
            }
        }
    }

private:
    std::vector<std::unique_ptr<Elevator>> cars_;
    std::unique_ptr<SchedulingStrategy> strategy_;
    int floors_;
    std::set<std::string> pending_;
};

