    ctrl.requestPickup(5, Direction::UP);   // rider on 5 going up
    ctrl.requestPickup(3, Direction::UP);   // rider on 3 going up
    for (int t = 0; t < 8; t++) ctrl.step();
    ctrl.requestFloor(0, 12);               // rider boarded car 0, wants 12
    for (int t = 0; t < 12; t++) ctrl.step();
    // one sweep serves 3, then 5, then 12
    return 0;
}

