from typing import List, Optional, Set


class InvalidFloorException(Exception):
    def __init__(self, floor: int): super().__init__(f"invalid floor {floor}")


class NoCarAvailableException(Exception): pass


class NearestCarStrategy(SchedulingStrategy):
    def pick_car(self, cars: List[Elevator], req: HallRequest) -> Optional[Elevator]:
        best: Optional[Elevator] = None
        best_score = float("inf")
        for car in cars:
            distance = abs(car.get_current_floor() - req.get_floor())
            on_the_way = (
                (car.get_direction() == Direction.UP and req.get_direction() == Direction.UP
                 and car.get_current_floor() <= req.get_floor())
                or (car.get_direction() == Direction.DOWN and req.get_direction() == Direction.DOWN
                    and car.get_current_floor() >= req.get_floor())
                or car.get_direction() == Direction.NONE
            )
            score = distance + (0 if on_the_way else 100)   # penalise cars going the wrong way
            if score < best_score:
                best_score = score
                best = car
        return best


class ElevatorController:
    def __init__(self, car_count: int, floors: int, strategy: SchedulingStrategy):
        self._floors = floors
        self._strategy = strategy
        self._cars: List[Elevator] = [Elevator(i) for i in range(car_count)]
        self._pending: Set[str] = set()

    def request_pickup(self, floor: int, direction: Direction) -> None:
        if floor < 0 or floor >= self._floors:
            raise InvalidFloorException(floor)
        key = f"{floor}:{direction}"
        if key in self._pending:
            return                          # atomic dedup
        self._pending.add(key)
        in_service = [c for c in self._cars if c.is_in_service()]
        if not in_service:
            self._pending.discard(key)
            raise NoCarAvailableException()
        self._strategy.pick_car(in_service, HallRequest(floor, direction)).add_stop(floor)

    def request_floor(self, car_id: int, floor: int) -> None:
        if floor < 0 or floor >= self._floors:
            raise InvalidFloorException(floor)
        self._cars[car_id].add_stop(floor)

    def step(self) -> None:
        for car in self._cars:
            before = car.get_current_floor()
            car.step()
            if car.get_current_floor() != before:           # clear served hall keys
                prefix = f"{car.get_current_floor()}:"
                self._pending = {k for k in self._pending if not k.startswith(prefix)}


if __name__ == "__main__":
    ctrl = ElevatorController(2, 15, NearestCarStrategy())
    ctrl.request_pickup(5, Direction.UP)    # rider on 5 going up
    ctrl.request_pickup(3, Direction.UP)    # rider on 3 going up
    for _ in range(8):
